'use client';

import { useState } from 'react';

import EmblaCarousel from '@/components/emblaCarousel/EmblaCarousel';
import Solar from '@/public/images/greenpower-source-solar.jpg';
import Wind from '@/public/images/greenpower-source-wind.jpg';

const sources = [
  {
    title: 'Solar',
    description:
      'Solar power is generated by capturing energy from sunlight using large-scale solar panels.',
    image: Solar,
    alt: 'Large-scale solar panels',
  },
  {
    title: 'Wind',
    description:
      'Wind power is generated by turbines that convert the movement of wind into renewable electricity.',
    image: Wind,
    alt: 'Wind power generation',
  },
];

const Sources = () => {
  const [activeIndex, setActiveIndex] = useState(0);
  const activeSource = sources[activeIndex];

  return (
    <section
      id='greenpower-sources'
      className='bg-brand-main text-light h-[789px]'
    >
      <div className='u-container py-section-main h-full'>
        <div className='flex h-full gap-(--size--4rem)'>
          <div
            id='greenpower-sources-carosuel'
            className='rounded-main relative flex-4 overflow-hidden'
          >
            <EmblaCarousel
              slides={sources.map(({ title, image, alt }) => ({
                title,
                image,
                alt,
              }))}
              onSlideChange={setActiveIndex}
            />
          </div>

          <div
            id='greenpower-sources-heading'
            className='relative flex flex-5 flex-col justify-between'
          >
            <h2 className='u-text-style-h3 !text-wrap'>
              ACX GreenPower is sourced from wind or large scale solar
            </h2>

            <div id='greenpower-sources-text' aria-live='polite'>
              <p className='u-text-style-h4 mb-fl-2'>{activeSource.title}</p>

              <p className='w-[60%]'>{activeSource.description}</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Sources;
